export function MainContent({
  heading = "{{heading}}",
  body = "{{body}}",
  padding = {{padding}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ display: "flex", height: 150, fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430", border: "1px solid #24143022" }}>
      <nav style={{ flex: "none", width: 64, background: "#241430", color: "#FAF7F2cc", fontSize: 12, textAlign: "center", paddingTop: 14 }}>Nav</nav>
      <main style={{ flex: 1, minWidth: 0, background: "#FAF7F2", boxSizing: "border-box", overflowY: "auto", padding, borderTop: `3px solid ${accent}` }}>
        <h3 style={{ margin: "0 0 8px" }}>{heading}</h3>
        <p style={{ margin: 0, color: "#241430cc" }}>{body}</p>
      </main>
    </div>
  );
}
